def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 3 or no_water_days >= 1:
            safe_bid = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, safe_bid)))

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    opp_req_pressure = 0.0

    for opp in alive_opponents:
        opp_req_pressure += float(opp.get('water_requirement', WATER_REQ))
        if float(opp.get('budget', 0.0)) >= 180:
            rich_count += 1
        if float(opp.get('hp', 10)) <= 3 or int(opp.get('no_water_days', 0)) >= 1:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0.0
    if supply <= 16:
        scarcity = 1.0
    elif supply <= 18:
        scarcity = 0.7
    elif supply <= 21:
        scarcity = 0.4
    else:
        scarcity = 0.15

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.65
    elif hp <= 6:
        urgency += 0.35

    if no_water_days >= 2:
        urgency += 0.9
    elif no_water_days >= 1:
        urgency += 0.45

    market_pressure = 0.0
    if highest_prev >= 260:
        market_pressure = 1.0
    elif highest_prev >= 210:
        market_pressure = 0.8
    elif highest_prev >= 150:
        market_pressure = 0.55
    elif highest_prev >= 90:
        market_pressure = 0.3
    else:
        market_pressure = 0.1

    opponent_threat = min(1.0, 0.22 * rich_count + 0.18 * desperate_count)

    score = 0.38 * scarcity + 0.34 * urgency + 0.18 * market_pressure + 0.10 * opponent_threat

    if hp >= 8 and no_water_days == 0 and supply >= 22 and highest_prev >= 180:
        score -= 0.18

    if day >= 8:
        score += 0.08
    if day >= 9:
        score += 0.08

    if score < 0.18:
        bid = DAILY_SALARY * 0.28
    elif score < 0.35:
        bid = DAILY_SALARY * 0.48
    elif score < 0.52:
        bid = max(DAILY_SALARY * 0.72, avg_prev * 0.55)
    elif score < 0.72:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    else:
        bid = max(DAILY_SALARY * 1.2, highest_prev + 8.0)

    if scarcity >= 0.7 and urgency >= 0.65:
        bid = max(bid, highest_prev + 10.0, DAILY_SALARY * 1.35)

    reserve = 0.0
    days_left = max(0, 10 - day)
    if days_left >= 3 and hp >= 5:
        reserve = DAILY_SALARY * 0.35
    elif days_left >= 1 and hp >= 3:
        reserve = DAILY_SALARY * 0.15

    max_affordable = max(0.0, budget - reserve)
    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)

    if budget < DAILY_SALARY * 0.5:
        bid = min(bid, budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    eric_alive = False
    eric_yesterday_bid = None

    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            if opp_id == "Eric":
                eric_alive = True
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])
                if opp_id == "Eric":
                    eric_yesterday_bid = prev['bid']

    if my_status['no_water_days'] > 0 or my_status['hp'] <= 3:
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            return min(my_status['budget'], max(DAILY_SALARY * 0.95, highest_prev_bid + 5))
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.95)

    base_moderate_bid = DAILY_SALARY * 0.55

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if eric_alive:
            if eric_yesterday_bid is not None and eric_yesterday_bid > DAILY_SALARY * 0.8:
                return min(my_status['budget'], max(base_moderate_bid, eric_yesterday_bid + 5))
            elif eric_yesterday_bid is not None:
                return min(my_status['budget'], max(base_moderate_bid, highest_prev_bid + 2))
            else:
                return min(my_status['budget'], max(base_moderate_bid, highest_prev_bid * 1.05 + 5))

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            return min(my_status['budget'], max(base_moderate_bid, highest_prev_bid + 2))
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            return min(my_status['budget'], max(base_moderate_bid, highest_prev_bid + 1))
        else:
            return min(my_status['budget'], base_moderate_bid)

    return min(my_status['budget'], base_moderate_bid)
